    : null;

  const worktrees: Worktree[] = (ws.worktrees || []).map((wt) => ({
    path: wt.path,
    branch: wt.branch ? (wt.branch.startsWith("refs/heads/") ? wt.branch : `refs/heads/${wt.branch}`) : null,
    head: wt.head,
    bare: false,
    detached: false,
    locked: wt.isLocked ? "locked" : null,
    prunable: null,
  }));

  const sessions: Record<string, TerminalSession> = {};
  for (const [id, sess] of Object.entries(ws.terminalSessions || {})) {
    const isLive = liveSet ? liveSet.has(sess.sessionId) : true;
    sessions[id] = {
      id: sess.sessionId,
      cwd: sess.cwd,
      workspaceId,
      worktree: null,
      backendSessionId: isLive ? sess.sessionId : null,
      lifecycle: "working",
    };
  }

  const tabs: WorkspaceTab[] = (ws.layout?.tabs || []).map((t) => {
    if (t.paneTree && (t.paneTree as any).type === "browser") {
      return {
        id: t.id,
        kind: "browser" as const,
        label: t.label,
        browserId: t.sessionId,
        url: "about:blank",
        title: t.label,
        canGoBack: false,
        canGoForward: false,
        loading: false,
      };
    }
    return {
      id: t.id,
      kind: "terminal" as const,
      sessionId: t.sessionId,
      label: t.label,
    };
  });

  const layoutsByTabId: LayoutState["layoutsByTabId"] = {};
  for (const t of ws.layout?.tabs || []) {
    if (!t.paneTree) continue;
    layoutsByTabId[t.id] = {
      root: t.paneTree,
      activeLeafId: t.activeLeafId || null,
      expandedLeafId: null,
      sessionIdsByLeafId: t.sessionIdsByLeafId || { [t.id]: t.sessionId },
    };
  }

  const tabGroups: Record<string, TabGroup> | undefined = ws.layout?.tabGroups?.length
    ? Object.fromEntries(
        ws.layout.tabGroups.map((group) => [
          group.id,
          { id: group.id, tabIds: [...group.tabIds], activeTabId: group.activeTabId },
        ]),
      )
    : undefined;

  const layout = normalizeLayout({
    tabs,
    primaryTabId: ws.layout?.primaryTabId || (tabs[0]?.id ?? null),
    secondaryTabId: ws.layout?.secondaryTabId || null,
    activeTabId: ws.layout?.activeTabId || (tabs[0]?.id ?? null),
    split: (ws.layout?.splitMode as any) || "none",
    nestedSplit: null,
    layoutsByTabId,
    tabGroups,
    tabGroupLayout: ws.layout?.tabGroupLayout ?? null,
    focusedGroupId: ws.layout?.focusedGroupId ?? null,
  });

  return {
    worktrees,
    activeWorktreePath: ws.activeWorktreePath || (worktrees[0]?.path ?? null),
    sessions,
    layout,
    unreadTabIds: {},
    unreadWorktreePaths: {},
  };
}

